(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11;
  const w2x = Math.sin((x+w1x)*0.025-t*0.4)*8 + Math.cos((y+w1y)*0.02+t*0.35)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.38)*7 + Math.sin((x+w1x)*0.028-t*0.42)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.9],
    [325+Math.cos(t*0.48)*105, 155+Math.sin(t*0.65)*55, 0.095, 1.8, 1.1],
    [240+Math.sin(t*0.28+2)*145, 115+Math.cos(t*0.45+1)*95, 0.055, 2.4, 0.8],
    [115+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.11, 1.6, 1.2],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.7],
    [240+Math.cos(t*0.32+5)*125, 205+Math.sin(t*0.52)*85, 0.085, 2.0, 1.0],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.13, 1.4, 1.3],
    [400+Math.cos(t*0.42+2)*60, 200+Math.sin(t*0.55+4)*55, 0.1, 1.9, 0.85]
  ];
  let aS=0, iS=0, a2=0, i2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((x-sX)**2+(y-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.68+t*sp*0.55+1.5)*w;
    a2 += Math.sin(d2*f*1.3-t*sp*0.8+2)*w*0.5;
    i2 += Math.cos(d*f*0.5+t*sp*0.4)*w*0.4;
  }
  const act=(aS+a2)/12, inh=(iS+i2)/12;
  const bg=(Math.sin(sx*0.038+sy*0.023+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.18+Math.sin((sx-sy)*0.095-t*1.9)*0.18;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.048-ang*3.5-t*1.4)+Math.sin(dist*0.038+ang*4.5-t*1.15))*0.35;
  const micro=Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.08-t*1.2)*0.15;
  const feed=Math.tanh((act-inh*0.65+bg*0.28+spiral+micro)*2.0);
  const lap = Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t)*0.45+Math.sin((sx-sy)*0.09-t*0.7)*0.3;
  const cell=Math.tanh(lap*1.4)*0.28;
  const diff=feed*0.6-cell*0.4;
  const sharp=1/(1+Math.exp(-diff*8));
  const blend=sharp*0.7+cell*0.2+feed*0.1, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,85],[18,90,120],[30,150,140],[180,195,80],
    [220,160,55],[200,100,60],[160,50,70],[90,22,55],[45,15,45],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(sharp*Math.PI)*0.18;
  const edge=Math.abs(diff)>0.35?1.12:1.0;
  const glow=Math.max(0,1-Math.abs(diff)*2.5)*0.15;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*180)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*220)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*255)|0)
  ];
}
